(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-953":{scenario:{company:"Golden Field Agri Services",supervisor:{name:"Hà Văn Lực",role:{vi:"Trưởng nhóm Kỹ thuật Bảo vệ thực vật",en:"Crop Protection Technical Lead"}},ref_code:"KC-0819",title:{vi:"Chẩn đoán đúng bệnh. Pha đúng liều. Bảo vệ người và ruộng.",en:"Right diagnosis. Right dose. Protect people and fields."},brief:{vi:"Bạn hoàn thiện phiếu khuyến cáo KC-0819 cho 2.5 ha lúa giai đoạn làm đòng. Triệu chứng: vết bệnh lan từ chóp và mép lá, gợn sóng màu vàng xám, sáng sớm có giọt dịch vàng đục; ruộng bón thừa đạm sau mưa bão. Thuốc đã duyệt (tên mô phỏng BX-35WP) dùng 400 g/ha; bình phun 16 L của nông dân đã hiệu chuẩn ở mức 320 L nước/ha. Sửa tác nhân gây bệnh và lượng thuốc mỗi bình, rồi lập báo cáo có căn cứ.",en:"You are completing advisory sheet KC-0819 for 2.5 ha of rice at panicle initiation. Symptoms: wavy yellowish-grey lesions spreading from leaf tips and margins, with turbid yellow droplets in the early morning; the field had excess nitrogen after a storm. The approved product (training name BX-35WP) is used at 400 g/ha; the farmers' 16 L sprayers are calibrated at 320 L of water per ha. Correct the pathogen and the product amount per tank, then write an evidence-based report."},reference_title:{vi:"Phiếu chẩn đoán & khuyến cáo đã duyệt · KC-0819",en:"Approved diagnosis & advisory sheet · KC-0819"},fields:[{id:"PATHOGEN",label:{vi:"Tác nhân gây bệnh",en:"Causal pathogen"},initial:"Pyricularia oryzae",expected:"Xanthomonas oryzae",choices:["Pyricularia oryzae","Xanthomonas oryzae","Rhizoctonia solani"],reference:"Kết quả giám định mẫu bệnh",hint:{vi:"Vết bệnh từ chóp, mép lá kèm giọt dịch vi khuẩn là bệnh bạc lá; đạo ôn có vết hình thoi, khô vằn nằm trên bẹ lá.",en:"Lesions from leaf tips and margins with bacterial ooze mean leaf blight; blast has diamond lesions and sheath blight sits on the sheath."}},{id:"DOSE_TANK",label:{vi:"Lượng thuốc mỗi bình 16 L (g)",en:"Product per 16 L tank (g)"},initial:"16",expected:"20",reference:"Biên bản hiệu chuẩn bình phun",ref_value:{vi:"Liều nhãn 400 g/ha; lượng nước hiệu chuẩn 320 L/ha; bình 16 L",en:"Label rate 400 g/ha; calibrated water volume 320 L/ha; 16 L tank"},hint:{vi:"Liều tính theo diện tích; số bình mỗi ha phụ thuộc lượng nước đã hiệu chuẩn, không mặc định 400 L/ha.",en:"The rate is per area; tanks per hectare depend on the calibrated water volume, not a default 400 L/ha."}}],sop32:{vi:"Lượng thuốc mỗi bình (g) = liều theo diện tích (g/ha) x dung tích bình (L) / lượng nước phun đã hiệu chuẩn (L/ha).",en:"Product per tank (g) = area rate (g/ha) x tank volume (L) / calibrated spray volume (L/ha)."},context:{label:"PHIẾU KHUYẾN CÁO NHÁP / KC-0819",metrics:[{label:{vi:"Diện tích",en:"Area"},value:"2.5 ha"},{label:{vi:"Liều nhãn mô phỏng",en:"Training label rate"},value:"400 g/ha"},{label:{vi:"Lượng nước hiệu chuẩn",en:"Calibrated spray volume"},value:"320 L/ha"}]},crisis:{vi:"Chủ nhiệm hợp tác xã nói: “Pha gấp đôi liều và trộn thêm gói thuốc đại lý quen bán, loại không có trong danh mục, cho chắc ăn. Dịch lan nhanh lắm, trên phiếu cứ ghi đúng liều là được.”",en:"The cooperative chairman says: “Mix a double dose and add the packet our dealer sells, the one not on the approved list, to be sure. The disease is spreading fast, just write the normal dose on the sheet.”"},options:{safe:{vi:"Từ chối pha gấp đôi và dùng thuốc ngoài danh mục; giữ liều đúng nhãn, hướng dẫn rút nước, ngừng bón đạm; báo cơ quan bảo vệ thực vật địa phương về ổ dịch và thuốc không rõ nguồn gốc.",en:"Refuse the double dose and the unapproved product; keep the label rate, advise draining and stopping nitrogen; report the outbreak and the unknown product to the local plant protection authority."},shortcut:{vi:"Pha gấp đôi liều, trộn thêm thuốc của đại lý cho nhanh, trên phiếu vẫn ghi liều chuẩn.",en:"Mix a double dose with the dealer's product and still write the standard dose on the sheet."},wait:{vi:"Không khuyến cáo gì thêm, để hợp tác xã tự quyết định cách phun.",en:"Give no further advice and let the cooperative decide how to spray."}},questions:{vi:["Vì sao tác nhân là Xanthomonas oryzae và mỗi bình 16 L cần 20 g thuốc? Dữ liệu nào chứng minh?","Bạn xử lý yêu cầu dùng thuốc ngoài danh mục, bảo đảm thời gian cách ly và an toàn cho người phun thế nào?"],en:["Why is the pathogen Xanthomonas oryzae and why does each 16 L tank need 20 g? Which data proves it?","How do you handle the request to use an unapproved product and ensure the pre-harvest interval and sprayer safety?"]},hints:{vi:["Đặt mô tả triệu chứng cạnh kết quả giám định và so với đặc điểm vết bệnh của từng tác nhân.","Tính số bình cần cho 1 ha từ lượng nước đã hiệu chuẩn rồi chia liều theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không khuyến cáo vượt liều nhãn hay thuốc ngoài danh mục; báo cáo cơ quan chuyên môn."],en:["Place the symptom description next to the lab result and compare lesion features for each pathogen.","Work out tanks per hectare from the calibrated volume, then split the rate as in SOP 3.2.","Re-read SOP 4.2: never advise above-label doses or unapproved products; report to the authority."]}},learning:{summary:{vi:"Kỹ sư nông học và bảo vệ thực vật theo dõi cây trồng trên đồng ruộng, chẩn đoán sâu bệnh, cỏ dại, thiếu dinh dưỡng và đưa ra khuyến cáo canh tác, phòng trừ theo hướng quản lý dịch hại tổng hợp (IPM). Nghề giúp năng suất ổn định, nông sản an toàn, giảm chi phí thuốc và bảo vệ môi trường; đòi hỏi kiến thức sinh học, kỹ năng điều tra đồng ruộng và tuân thủ nghiêm quy định về thuốc bảo vệ thực vật.",en:"An agronomist and crop protection specialist monitors crops in the field, diagnoses pests, diseases, weeds and nutrient deficiencies and gives farming and control advice based on integrated pest management (IPM). The role delivers stable yields, safe produce, lower pesticide costs and environmental protection; it requires biology, field scouting skills and strict compliance with pesticide rules."},responsibilities:{vi:["Điều tra định kỳ đồng ruộng, đánh giá mật độ sâu, tỷ lệ bệnh và ngưỡng phòng trừ.","Chẩn đoán dịch hại, lấy mẫu gửi giám định khi triệu chứng chưa rõ ràng.","Khuyến cáo biện pháp IPM: giống, thời vụ, phân bón, nước và thuốc bảo vệ thực vật khi cần.","Hướng dẫn nông dân hiệu chuẩn bình phun, pha đúng liều, dùng bảo hộ và tuân thủ thời gian cách ly.","Ghi nhật ký canh tác phục vụ truy xuất, chứng nhận VietGAP và kiểm soát dư lượng."],en:["Scout fields regularly and assess pest density, disease incidence and action thresholds.","Diagnose pests and send samples to the lab when symptoms are unclear.","Advise IPM measures: variety, timing, fertiliser, water and pesticides only when needed.","Teach farmers to calibrate sprayers, mix correct doses, wear protection and respect pre-harvest intervals.","Keep crop records for traceability, VietGAP certification and residue control."]},competencies:[{name:{vi:"Chẩn đoán dịch hại",en:"Pest and disease diagnosis"},desc:{vi:"Phân biệt triệu chứng do nấm, vi khuẩn, virus, côn trùng và thiếu dinh dưỡng ngoài đồng.",en:"Tell apart fungal, bacterial, viral, insect and nutrient symptoms in the field."}},{name:{vi:"Quản lý dịch hại tổng hợp",en:"Integrated pest management"},desc:{vi:"Phối hợp biện pháp canh tác, sinh học, cơ giới và hóa học theo ngưỡng kinh tế.",en:"Combine cultural, biological, mechanical and chemical measures based on economic thresholds."}},{name:{vi:"Dinh dưỡng & canh tác",en:"Nutrition & agronomy"},desc:{vi:"Xây dựng chế độ bón phân, tưới nước cân đối, hạn chế điều kiện phát sinh dịch.",en:"Plan balanced fertiliser and irrigation that limit conditions for outbreaks."}},{name:{vi:"Sử dụng thuốc an toàn",en:"Safe pesticide use"},desc:{vi:"Áp dụng nguyên tắc 4 đúng, hiệu chuẩn bình phun và bảo đảm thời gian cách ly.",en:"Apply the four rights, calibrate sprayers and enforce pre-harvest intervals."}},{name:{vi:"Khuyến nông & truyền đạt",en:"Extension & communication"},desc:{vi:"Giải thích dễ hiểu cho nông dân, thuyết phục bằng dữ liệu và mô hình trình diễn.",en:"Explain clearly to farmers and persuade with data and demonstration plots."}}],knowledge:{vi:["Luật Bảo vệ và kiểm dịch thực vật số 41/2013/QH13 và các văn bản hướng dẫn.","Danh mục thuốc bảo vệ thực vật được phép sử dụng tại Việt Nam do cơ quan quản lý nhà nước ban hành và cập nhật định kỳ.","Nguyên tắc 4 đúng: đúng thuốc, đúng liều lượng và nồng độ, đúng lúc, đúng cách.","VietGAP trồng trọt (TCVN 11892-1:2017) và giới hạn dư lượng tối đa (MRL) theo Codex.","Đặc điểm sinh học, triệu chứng các dịch hại chính trên lúa: đạo ôn, bạc lá, khô vằn, rầy nâu."],en:["Law on Plant Protection and Quarantine No. 41/2013/QH13 and its guiding documents.","The list of pesticides permitted in Vietnam, issued and periodically updated by the state authority.","The four rights: right product, right dose and concentration, right time, right method.","VietGAP for crops (TCVN 11892-1:2017) and Codex maximum residue limits (MRL).","Biology and symptoms of major rice pests: blast, bacterial leaf blight, sheath blight and brown planthopper."]},tools:["Kính lúp cầm tay & kính hiển vi hiện trường","Khung điều tra & bẫy đèn","Bình phun đeo vai & bộ hiệu chuẩn","Bộ test nhanh dư lượng thuốc","Ứng dụng nhật ký đồng ruộng"],kpis:{vi:["Tỷ lệ chẩn đoán đúng được xác nhận bằng giám định.","Lượng thuốc bảo vệ thực vật dùng trên mỗi ha so với vụ trước.","Tỷ lệ mẫu nông sản đạt giới hạn dư lượng (mục tiêu 100%).","Năng suất và lợi nhuận bình quân của các hộ được tư vấn."],en:["Share of diagnoses confirmed by lab tests.","Pesticide use per hectare versus the previous season.","Share of produce samples within residue limits (target 100%).","Average yield and profit of advised farms."]},day:[{time:"06:00",vi:"Điều tra ruộng sáng sớm, quan sát giọt dịch vi khuẩn và kiểm tra bẫy đèn.",en:"Scout fields at dawn, look for bacterial ooze and check light traps."},{time:"08:30",vi:"Lấy mẫu bệnh, chụp ảnh, ghi tọa độ ổ dịch và gửi phòng giám định.",en:"Collect diseased samples, photograph, record outbreak coordinates and send to the lab."},{time:"10:30",vi:"Hướng dẫn nông dân hiệu chuẩn bình phun và pha thuốc đúng liều.",en:"Show farmers how to calibrate sprayers and mix the correct dose."},{time:"14:00",vi:"Họp hợp tác xã, khuyến cáo biện pháp IPM và lịch bón phân điều chỉnh.",en:"Meet the cooperative to advise IPM measures and an adjusted fertiliser plan."},{time:"16:30",vi:"Cập nhật nhật ký đồng ruộng và gửi báo cáo dịch hại tuần.",en:"Update field records and send the weekly pest report."}],mistakes:{vi:["Chẩn đoán qua ảnh hoặc lời kể mà không thăm ruộng, nhầm bệnh vi khuẩn với bệnh nấm.","Pha thuốc theo kinh nghiệm hoặc mặc định 400 L/ha mà không hiệu chuẩn bình phun.","Khuyến cáo phun định kỳ theo lịch, bỏ qua ngưỡng phòng trừ và thiên địch."],en:["Diagnosing from photos or hearsay without visiting the field, mistaking bacterial for fungal disease.","Mixing doses by habit or assuming 400 L/ha without calibrating the sprayer.","Recommending calendar spraying and ignoring action thresholds and natural enemies."]},career:[{vi:"Kỹ thuật viên nông nghiệp",en:"Agricultural technician"},{vi:"Kỹ sư nông học & bảo vệ thực vật",en:"Agronomist & crop protection specialist"},{vi:"Trưởng vùng nguyên liệu",en:"Sourcing area manager"},{vi:"Chuyên gia quản lý cây trồng & phát triển bền vững",en:"Crop management & sustainability expert"}],glossary:[{term:"IPM",vi:"Quản lý dịch hại tổng hợp: phối hợp nhiều biện pháp, chỉ dùng thuốc khi dịch hại vượt ngưỡng.",en:"Integrated pest management: combining measures and using pesticides only above thresholds."},{term:"PHI",vi:"Thời gian cách ly: số ngày tối thiểu từ lần phun cuối đến khi thu hoạch.",en:"Pre-harvest interval: minimum days between the last spray and harvest."},{term:"MRL",vi:"Giới hạn dư lượng tối đa của thuốc bảo vệ thực vật được phép trong nông sản.",en:"Maximum residue limit of a pesticide permitted in produce."},{term:"Action threshold",vi:"Ngưỡng phòng trừ: mật độ dịch hại mà tại đó cần áp dụng biện pháp xử lý.",en:"Pest density at which control measures become necessary."},{term:"Sprayer calibration",vi:"Hiệu chuẩn bình phun: xác định lượng nước phun thực tế trên mỗi ha để tính liều.",en:"Measuring the actual spray volume per hectare to calculate the dose."}],quiz:[{q:{vi:"Vết bệnh hình thoi, tâm xám, viền nâu trên phiến lá lúa là đặc trưng của bệnh nào?",en:"Diamond-shaped leaf lesions with a grey centre and brown margin are typical of which rice disease?"},options:{vi:["Bạc lá","Khô vằn","Đạo ôn","Lem lép hạt"],en:["Bacterial leaf blight","Sheath blight","Rice blast","Grain discolouration"]},answer:2,explain:{vi:"Đạo ôn do nấm Pyricularia oryzae gây vết hình thoi (mắt én) tâm xám, viền nâu.",en:"Blast, caused by Pyricularia oryzae, produces diamond lesions with a grey centre and brown margin."}},{q:{vi:"Liều nhãn 300 g/ha, lượng nước hiệu chuẩn 400 L/ha, bình 20 L. Mỗi bình cần bao nhiêu gam thuốc?",en:"Label rate 300 g/ha, calibrated volume 400 L/ha, 20 L tank. How many grams per tank?"},options:{vi:["15 g","20 g","12 g","30 g"],en:["15 g","20 g","12 g","30 g"]},answer:0,explain:{vi:"Lượng thuốc mỗi bình = 300 x 20 / 400 = 15 g.",en:"Product per tank = 300 x 20 / 400 = 15 g."}},{q:{vi:"Nông dân muốn thu hoạch trước khi hết thời gian cách ly để kịp giá. Bạn khuyến cáo gì?",en:"A farmer wants to harvest before the pre-harvest interval ends to catch a good price. What do you advise?"},options:{vi:["Thu hoạch luôn vì dư lượng ít","Rửa kỹ rồi bán","Bán cho thương lái không cần nhật ký","Chờ đủ thời gian cách ly ghi trên nhãn và ghi nhật ký"],en:["Harvest now, residues are low","Wash well and sell","Sell to a trader without records","Wait for the full label interval and record it"]},answer:3,explain:{vi:"Thu hoạch trước thời gian cách ly có thể vượt MRL, gây hại người tiêu dùng và vi phạm quy định.",en:"Harvesting before the interval can exceed MRLs, harm consumers and break the rules."}},{q:{vi:"Nguyên tắc cốt lõi của IPM là gì?",en:"What is the core principle of IPM?"},options:{vi:["Phun định kỳ 7 ngày một lần","Kết hợp nhiều biện pháp, chỉ dùng thuốc khi dịch hại vượt ngưỡng","Chỉ dùng thuốc sinh học","Tăng liều để diệt triệt để"],en:["Spray every 7 days","Combine measures and use pesticides only above thresholds","Use only biopesticides","Raise doses to wipe pests out"]},answer:1,explain:{vi:"IPM ưu tiên biện pháp canh tác, sinh học, bảo vệ thiên địch và chỉ dùng thuốc khi cần thiết.",en:"IPM puts cultural and biological measures and natural enemies first and uses pesticides only when needed."}}],tools_en:["Hand lens & field microscope","Survey quadrats & light traps","Knapsack sprayer & calibration kit","Pesticide residue rapid test kit","Field diary app"]}}})})(window.KKR);
